#include "character_update_eligibility.hpp"
#include <cassert>
#include <cstdint>
#include <iostream>
namespace eu=dh2::character_update_eligibility;
struct Fixture {
 eu::SceneNode node{0x3001,1,9,{}};
 eu::Visual visual{0x2001,&node};
 eu::Character character{0x1001,&visual,0x7001,1,0,0,0};
 eu::Result result{0xabcd,eu::Outcome::allowed,0x1234,99,88};
 eu::Services services{};
 std::uint32_t online=1,remote=1,local=0x7002;
 int mutate=0,calls=0;
 alignas(eu::SceneNode) unsigned char bytes[sizeof(eu::SceneNode)+1]{};
 Fixture();
};
static std::int32_t invoke(void* p,const eu::Character*,const eu::Request* q,eu::Response* r) {
 auto& f=*static_cast<Fixture*>(p);++f.calls;
 switch(q->operation) {
 case eu::Operation::get_online_byte:
  r->raw=f.online;
  switch(f.mutate) {
  case 1:f.visual.root=nullptr;break;
  case 2:f.visual.root=reinterpret_cast<eu::SceneNode*>(&f.character);break;
  case 3:f.visual.root=reinterpret_cast<eu::SceneNode*>(&f.result);break;
  case 4:f.visual.root=reinterpret_cast<eu::SceneNode*>(&f.services);break;
  case 5:f.visual.root=reinterpret_cast<eu::SceneNode*>(f.bytes+1);break;
  case 6:f.services.invoke=nullptr;break;
  }
  return 0;
 case eu::Operation::is_remotely_updated:r->raw=f.remote;return 0;
 case eu::Operation::local_player_character:
  r->identity=f.local;
  switch(f.mutate) {
  case 7:f.character.visual_2d8=nullptr;break;
  case 8:f.character.visual_2d8=reinterpret_cast<eu::Visual*>(&f.character);break;
  case 9:f.character.visual_2d8=reinterpret_cast<eu::Visual*>(&f.result);break;
  case 10:f.visual.root=reinterpret_cast<eu::SceneNode*>(&f.result);break;
  }
  return 0;
 case eu::Operation::test_culling_before_update:r->raw=1;return 0;
 case eu::Operation::is_dead:r->raw=0;return 0;
 case eu::Operation::can_respawn:r->raw=1;return 0;
 }
 return 1;
}
Fixture::Fixture(){services={this,invoke};}
int main() {
 std::uint32_t count=0;
 auto initial=[&](Fixture& f,eu::Status wanted,eu::Character* c,const eu::Services* s,eu::Result* r){
  assert(eu::evaluate(c,s,r)==wanted);assert(f.calls==0&&f.node.update_flag_200==9);
  assert(f.result.can_update==0xabcd&&f.result.service_calls==99);++count;
 };
 {Fixture f;initial(f,eu::Status::invalid_argument,nullptr,&f.services,&f.result);}
 {Fixture f;initial(f,eu::Status::invalid_argument,&f.character,nullptr,&f.result);}
 {Fixture f;initial(f,eu::Status::invalid_argument,&f.character,&f.services,nullptr);}
 {Fixture f;f.character.identity=0;initial(f,eu::Status::invalid_argument,&f.character,&f.services,&f.result);}
 {Fixture f;alignas(eu::Character) unsigned char b[sizeof(eu::Character)+1]{};initial(f,eu::Status::invalid_argument,reinterpret_cast<eu::Character*>(b+1),&f.services,&f.result);}
 {Fixture f;alignas(eu::Services) unsigned char b[sizeof(eu::Services)+1]{};initial(f,eu::Status::invalid_argument,&f.character,reinterpret_cast<eu::Services*>(b+1),&f.result);}
 {Fixture f;alignas(eu::Result) unsigned char b[sizeof(eu::Result)+1]{};initial(f,eu::Status::invalid_argument,&f.character,&f.services,reinterpret_cast<eu::Result*>(b+1));}
 {Fixture f;initial(f,eu::Status::invalid_argument,&f.character,&f.services,reinterpret_cast<eu::Result*>(&f.character));}
 {Fixture f;initial(f,eu::Status::invalid_argument,&f.character,&f.services,reinterpret_cast<eu::Result*>(&f.services));}
 {Fixture f;initial(f,eu::Status::invalid_argument,&f.character,reinterpret_cast<eu::Services*>(&f.character),&f.result);}
 {Fixture f;f.visual.identity=0;initial(f,eu::Status::invalid_source_fact,&f.character,&f.services,&f.result);}
 {Fixture f;f.node.identity=0;initial(f,eu::Status::invalid_source_fact,&f.character,&f.services,&f.result);}
 {Fixture f;f.visual.root=nullptr;initial(f,eu::Status::invalid_source_fact,&f.character,&f.services,&f.result);}
 {Fixture f;f.visual.root=reinterpret_cast<eu::SceneNode*>(f.bytes+1);initial(f,eu::Status::invalid_source_fact,&f.character,&f.services,&f.result);}
 for(int m:{1,2,3,4,5}) {
  Fixture f;f.mutate=m;
  assert(eu::evaluate(&f.character,&f.services,&f.result)==eu::Status::invalid_source_fact);
  assert(f.calls==2&&f.node.update_flag_200==0&&f.result.scene_flag_writes==1);
  assert(f.result.can_update==0&&f.result.service_calls==2);++count;
 }
 for(int m:{7,8,9,10}) {
  Fixture f;f.online=0;f.mutate=m;
  assert(eu::evaluate(&f.character,&f.services,&f.result)==eu::Status::invalid_source_fact);
  assert(f.calls==2&&f.node.update_flag_200==0&&f.result.scene_flag_writes==1);++count;
 }
 {Fixture f;f.mutate=6;assert(eu::evaluate(&f.character,&f.services,&f.result)==eu::Status::complete);
  assert(f.calls==2&&f.result.can_update==1&&f.node.update_flag_200==1&&f.result.scene_flag_writes==2);++count;}
 std::cout<<"{\"validation\":\"PASS\",\"independent_projection_guard_cases\":"<<count<<",\"source_failure_prefix_preserved\":true,\"bound_services_retained\":true}\n";
}
